describe("Jest Matchers", () => {
  // Equality
  test("object equality", () => {
    const user = { name: "An", age: 20 };
    expect(user).toEqual({ name: "An", age: 20 }); // deep
    expect(user).not.toBe({ name: "An", age: 20 }); // different ref
  });

  // Truthiness
  test("truthy/falsy", () => {
    expect(null).toBeNull();
    expect(undefined).toBeUndefined();
    expect("hello").toBeTruthy();
    expect(0).toBeFalsy();
  });

  // Arrays & Iterables
  test("arrays", () => {
    const list = ["apple", "banana", "cherry"];
    expect(list).toContain("banana");
    expect(list).toHaveLength(3);
    expect(list).toEqual(expect.arrayContaining(["apple", "cherry"]));
  });

  // Objects
  test("object matching", () => {
    const response = { status: 200, data: { id: 1, name: "An" } };
    expect(response).toMatchObject({
      status: 200,
      data: expect.objectContaining({ name: "An" })
    });
  });

  // Strings
  test("string matching", () => {
    expect("hello world").toMatch(/world/);
    expect("Error: not found").toContain("not found");
  });
});

class TodoList {
  constructor() { this.todos = []; this.nextId = 1; }
  add(title) {
    const todo = { id: this.nextId++, title, done: false };
    this.todos.push(todo);
    return todo;
  }
  toggle(id) {
    const todo = this.todos.find(t => t.id === id);
    if (!todo) throw new Error("Not found");
    todo.done = !todo.done;
    return todo;
  }
  getAll(filter) {
    if (filter === "done") return this.todos.filter(t => t.done);
    if (filter === "active") return this.todos.filter(t => !t.done);
    return [...this.todos];
  }
}

describe("TodoList", () => {
  let todoList;

  beforeEach(() => {
    // Arrange: fresh instance for each test
    todoList = new TodoList();
  });

  describe("add()", () => {
    test("should add todo with auto-incremented id", () => {
      const todo = todoList.add("Learn Jest");
      expect(todo).toEqual({ id: 1, title: "Learn Jest", done: false });
    });

    test("should increment id for each todo", () => {
      todoList.add("First");
      const second = todoList.add("Second");
      expect(second.id).toBe(2);
    });
  });

  describe("toggle()", () => {
    test("should toggle done status", () => {
      todoList.add("Task");
      const toggled = todoList.toggle(1);
      expect(toggled.done).toBe(true);
    });

    test("should throw for invalid id", () => {
      expect(() => todoList.toggle(999)).toThrow("Not found");
    });
  });
});

// userService.js
class UserService {
  constructor(database, emailSender) {
    this.db = database;
    this.email = emailSender;
  }
  async createUser(name, email) {
    const user = await this.db.save({ name, email });
    await this.email.sendWelcome(email, name);
    return user;
  }
}

// userService.test.js
describe("UserService", () => {
  let service, mockDb, mockEmail;

  beforeEach(() => {
    mockDb = {
      save: jest.fn().mockResolvedValue({ id: 1, name: "An", email: "a@b.com" }),
      findById: jest.fn()
    };
    mockEmail = {
      sendWelcome: jest.fn().mockResolvedValue(true)
    };
    service = new UserService(mockDb, mockEmail);
  });

  test("createUser saves to db and sends email", async () => {
    const user = await service.createUser("An", "a@b.com");

    expect(user.id).toBe(1);
    expect(mockDb.save).toHaveBeenCalledWith({
      name: "An", email: "a@b.com"
    });
    expect(mockDb.save).toHaveBeenCalledTimes(1);
    expect(mockEmail.sendWelcome).toHaveBeenCalledWith("a@b.com", "An");
  });

  test("should not send email if db fails", async () => {
    mockDb.save.mockRejectedValue(new Error("DB Error"));
    await expect(service.createUser("X", "x@y.com")).rejects.toThrow("DB Error");
    expect(mockEmail.sendWelcome).not.toHaveBeenCalled();
  });
});

// async functions
async function fetchUser(id) {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) throw new Error(`User ${id} not found`);
  return res.json();
}

function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

