// Step 1: RED - Write failing test first
describe("PasswordValidator", () => {
  test("rejects empty password", () => {
    expect(validate("")).toEqual({
      valid: false,
      errors: ["Password is required"]
    });
  });

  test("rejects short password", () => {
    expect(validate("abc")).toEqual({
      valid: false,
      errors: ["Minimum 8 characters"]
    });
  });

  test("requires uppercase letter", () => {
    const result = validate("abcdefgh");
    expect(result.valid).toBe(false);
    expect(result.errors).toContain("Needs uppercase letter");
  });

  test("accepts valid password", () => {
    expect(validate("Abcdef1!")).toEqual({
      valid: true, errors: []
    });
  });
});

// Step 2: GREEN - Minimum code to pass
function validate(password) {
  const errors = [];
  if (!password) errors.push("Password is required");
  else {
    if (password.length < 8) errors.push("Minimum 8 characters");
    if (!/[A-Z]/.test(password)) errors.push("Needs uppercase letter");
    if (!/[0-9]/.test(password)) errors.push("Needs a number");
  }
  return { valid: errors.length === 0, errors };
}

